// Sample code to reproduce the issue of missing width and height attributes in images

const images = [
  {
    src: '/img/community.jpg',
    alt: 'The Apache Community',
    class: 'img-responsive',
  },
  {
    src: '/img/asf-estd-1999-logo.jpg',
    alt: 'Apache 20th Anniversary Logo',
    class: 'img-responsive center-block visible-home',
  },
  {
    src: '/img/ApacheCon.jpg',
    alt: 'ApacheCon',
    class: 'img-responsive',
  },
  {
    src: '/img/the-apache-way.jpg',
    alt: 'The Apache Way',
    class: 'img-responsive',
  },
];

// Function to render images without width and height
function renderImages(images) {
  const container = document.getElementById('image-container');
  images.forEach(image => {
    const imgElement = document.createElement('img');
    imgElement.src = image.src;
    imgElement.alt = image.alt;
    imgElement.className = image.class;
    container.appendChild(imgElement);
  });
}

// Call the function to render images
renderImages(images);
